def max_value_on_paths(N, grid_values):
    grid = [[0 for _ in range(N)] for _ in range(N)]
    for x, y, value in grid_values:
        if value:
            grid[x][y] = value

    def dfs(x, y, prev_path, max_sum):
        if x == N-1 and y == N-1:
            max_sum[0] = max(max_sum[0], prev_path)
            return

        if x < 0 or y < 0 or x >= N or y >= N:
            return

        for nx, ny in [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]:
            dfs(nx, ny, prev_path + grid[nx][ny], max_sum)

    max_sum = [0]
    dfs(0, 0, 0, max_sum)
    return max_sum[0]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    def eleate(sub_grid_data, memo):
        if len(sub_grid_data) == 1:
            x, y, value = sub_grid_data[0]
            return [((x, y), value)]

        next niveau = []
        for next_index in range(2):
            value = sub_grid_data[next_index][2]
            sub_grid = eleate(sub_grid_data[:next_index] + sub_grid_data[next_index + 1:], memo)
            for idx, (position, existing_value) in enumerate(sub_grid):
                if existing_value == 0 or idx != len(sub_grid) - 1:
                    candidate = value + existing_value
                    memo[position] = max(memo[position], candidate)
                    next_niveau.append((position, candidate))

        return next_niveau

    grid_values.remove((0, 0, 0))
    sub_grid_data = [grid_values[x + (y * N)] for x in range(N) for y in range(N)]
    memo = {(x, y): 0 for x in range(N) for y in range(N)}
    eleated_grid_data = eleate(sub_grid_data, memo)

    max_path_a = max(eleated_grid_data, key=lambda x: x[1][N - 1])
    eleated_grid_data.remove(max_path_a)
    max_path_b = max(eleated_grid_data, key=lambda x: x[1][N - 1])
    return max(max_path_a, max_path_b, key=lambda x: sum(x[1]))

