def max_energy(beads):
    n = len(beads)
    dp = [[-1 for _ in range(n)] for _ in range(n)]

    @lru_cache(maxsize=None)
    def max_energy_recursive(i, j):
        if dp[i][j] != -1:
            return dp[i][j]

        if i == j:
            return beads[i]

        max_val = -1
        for k in range(i, j):
            if beads[i] == beads[k] and beads[k + 1] == beads[j]:
                energy = beads[i] * beads[(k + 1) % n] * beads[j]
                max_val = max(max_val, energy + max_energy_recursive(i, k) + max_energy_recursive(k + 1, j))

        dp[i][j] = max_val
        return max_val

    return max_energy_recursive(0, n - 1)

