    for mask in range(1 << n):
        for i in range(n):
            if mask & (1 << i):
                mask_with_i = mask ^ (1 << i)
                if mask_with_i and i + 1 < n and beads[i] == beads[mask_with_i & ~(1 << i)]:
                    dp[mask] = max(dp[mask], dp[mask_with_i] * beads[i])

    return dp[(1 << n) - 1]

