                    res += 2
    return res

def count_coprime_pairs(x0: int, y0: int) -> int:
    pairs_count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        b = quotient // a
        if gcd(a, b) == 1:
            if a == b:
                pairs_count += 1
            else:
                pairs_count += 2
    return pairs_count

def count_coprime_pairs(x0, y0):
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        if y0 % a == 0 and x0 % a == 0:
            b = quotient // a
            if x0 == a == b:
                count += 1
            else:
                count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    n = len(inorder)
    # Dictionary to store the index of each element in the inorder traversal
    idx_map = {x: i for i, x in enumerate(inorder)}

    def construct_tree(in_order, low, high, post_order, idx):
        if low > high:
            return []
        root = TreeNode(post_order[idx])
        idx_p = idx_map[root.val]
        root.left = construct_tree(in_order, low, idx_p - 1, post_order, idx - 1 - (high - idx_p))
        root.right = construct_tree(in_order, idx_p + 1, high, post_order, idx - 1)
        return root

    r = construct_tree(inorder, 0, n - 1, postorder, n - 1)
    return preorder(r)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root_val = postorder[-1]

    root_val_pos = inorder.find(root_val)

    left_inorder = inorder[:root_val_pos]
    right_inorder = inorder[root_val_pos + 1:]

    left_postorder = postorder[:root_val_pos]
    right_postorder = postorder[root_val_pos + 1:-1]

    return preorder_val + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root = postorder[-1]
    index = inorder.index(root)

    left_subtree_inorder = inorder[:index]
    right_subtree_inorder = inorder[index + 1:]
    left_subtree_postorder = postorder[:index]
    right_subtree_postorder = postorder[index:-1]

    return root + preorder_traversal(left_subtree_inorder, left_subtree_postorder) + preorder_traversal(right_subtree_inorder, right_subtree_postorder)

