def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:

    # Initialize a dynamic programming table with zeros
    dp = [[0 for _ in range(T + 1)] for _ in range(M + 1)]

    # Fill the dp table
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(1, T + 1):
            if time <= j:
                dp[i][j] = max(dp[i - 1][j], value + dp[i - 1][j - time])

    # The maximum total value is the last element in the dp table
    return dp[M][T]

