def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Helper function to calculate the value of a subset of herbs
    def recursive_max_herb_value(remaining_time: int, remaining_herbs: List[Tuple[int, int]]):
        if not remaining_herbs:
            return 0
        herb, value = remaining_herbs[0]
        if herb <= remaining_time:
            # Take the herb
            return value + recursive_max_herb_value(remaining_time - herb, remaining_herbs[1:])
            # Skip the herb
            return recursive_max_herb_value(remaining_time, remaining_herbs[1:])
        else:
            return recursive_max_herb_value(remaining_time, remaining_herbs[1:])

    # Start the recursive function with the total time and a list of herbs
    return recursive_max_herb_value(T, herbs)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    def dfs(current_time, remaining_time, value):
        if current_time > T:
            return 0
        if remaining_time == 0:
            return value
        a = dfs(current_time + herbs[-1][0], remaining_time - 1, value + herbs[-1][1])
        b = dfs(current_time, remaining_time - 1, value)
        return max(a, b)

    herbs.sort(key=lambda x: (-x[1], x[0]))  # Sort herbs by value in descending order and time ascending order
    return dfs(0, T, 0)

