class Solution:
    def min_remaining_space(self, V: int, n: int, volumes: List[int]) -> int:
        dp = [[0] * (V + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, V + 1):
                if volumes[i - 1] <= j:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
                else:
                    dp[i][j] = dp[i - 1][j]
        return V - dp[n][V]

