def calculate_arrangements(n: int, m: int, a: List[int]) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k] % MOD) % MOD

    return dp[n][m]

def calculate_arrangements(n, m, a):
    mod = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % mod
            if j <= a[i - 1]:
                dp[i][j] = (dp[i][j] - dp[i][j - a[i - 1]] + mod) % mod

    return dp[n][m]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [[0]*(m+1) for _ in range(n+1)]

    for i in range(n+1):
        for j in range(m+1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif j == 1 and i == 1:
                dp[i][j] = 1
            elif i == j:
                dp[i][j] = dp[i-1][j-1] * (j + 1) % MOD
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1] * max(0, i - a[j-1]) % MOD

    return dp[n][m]

