def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    decrypted_text = ""
    key_index = 0

    for char in ciphertext:
        if char.isalpha():
            shift = ord(key[key_index % key_length]) - ord('A')
            decrypted_char = chr(((ord(char) - ord('A') - shift) % 26) + ord('A'))
            decrypted_text += decrypted_char
            key_index += 1
        else:
            decrypted_text += char

    return decrypted_text

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    decrypted_text = ""
    for char in ciphertext:
        if char.isalpha():
            shift = ord(key[(ciphertext.index(char) // key_length) % key_length].lower()) - ord('a')
            decrypted_char = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            decrypted_text += decrypted_char
        else:
            decrypted_text += char
    return decrypted_text

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    from string import ascii_lowercase
    def shift_char(char: str, shift: int) -> str:
        if char.islower():
            return ascii_lowercase[(ascii_lowercase.index(char) - shift) % 26]
        elif char.isupper():
            return ascii_uppercase[(ascii_uppercase.index(char) - shift) % 26]
        return char

    key_index = 0
    plaintext = ''

    for char in ciphertext:
        if char.isalpha():
            shift = ascii_lowercase.index(key[key_index % len(key)]) if char.islower() else ascii_uppercase.index(key[key_index % len(key)])
            plaintext += shift_char(char, -shift)
            key_index += 1
        else:
            plaintext += char

    return plaintext

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def caesar_decrypt(char, shift):
        if char.isalpha():
            shift = shift % 26
            if char.islower():
                return chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            else:
                return chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
        return char

    plaintext = ""
    key_length = len(key)
    ciphertext_length = len(ciphertext)

    for i in range(ciphertext_length):
        shift = ord(key[i % key_length]) - ord('A')
        plaintext += caesar_decrypt(ciphertext[i], -shift)

    return plaintext

def mod_inverse(a, b):
    # Extended Euclidean Algorithm to find the modular multiplicative inverse
    x0, x1, y0, y1 = 0, 1, 1, 0

    while b:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1 - quotient * x0, x0
        y0, y1 = y1 - quotient * y0, y1

    if a != 1:
        return None  # Inverse does not exist
    else:
        return (x0 + b) % b

def mod_inverse(a, b):
    if b == 0:
        return None
    x0, x1 = 0, 1
    while a != 0:
        quotient = b // a
        b, a = a, b % a
        x0, x1 = x1 - quotient * x0, x0
    return x1 % b

def mod_inverse(a, b):
    if a == 0 or b == 0:
        return None

    x, y, u, y1, v, w = 0, 1, 1, 0, 0, 1
    while b:
        q = a // b
        a, b = b, a % b
        x, u = u, x - q * u
        y, y1 = y1, y - q * y1
        v, w = w, v - q * w

    if x < 0:
        x += b

    return x

