def find_most_unhappy_day(schedule) -> int:
    if not schedule:
        return 0

    max_hour = -float('inf')
    shortest_idx = 0

    for i in range(7):
        total_hours = schedule[i][0] + schedule[i][1]
        if total_hours > max_hour:
            max_hour = total_hours
            shortest_idx = i

    return shortest_idx + 1

def find_most_unhappy_day(schedule) -> int:
    total_hours = lambda day: schedule[day][0] + schedule[day][1]
    threshold = 8
    unhappy_days = []
    earliest_start_day = 0
    earliest_start_time = 24

    for day in range(7):
        if total_hours(day) > threshold:
            unhappy_days.append(day)
            if total_hours(day) < earliest_start_time or (total_hours(day) == earliest_start_time and day < earliest_start_day):
                earliest_start_day = day
                earliest_start_time = total_hours(day)

    if not unhappy_days:
        return 0
    return earliest_start_day + 1  # Convert day index to 1-7 day representation

def find_most_unhappy_day(schedule) -> int:
    threshold = 8
    max_unhappy_day = 0
    days_of_week = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    max_unhappy_count = 0

    for i, (hours_at_school, extra_classes) in enumerate(schedule):
        total_hours = hours_at_school + extra_classes
        if total_hours > threshold:
            happiness = total_hours - threshold
            if happiness > max_unhappy_count:
                max_unhappy_day = i + 1
                max_unhappy_count = happiness
            elif happiness == max_unhappy_count:
                max_unhappy_day = min(max_unhappy_day, i + 1)

    if max_unhappy_day == 0:
        return 0
    else:
        return max_unhappy_day

def next_permutation(perm: list) -> bool:
    if not perm:
        return False

    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i + 1]:
        i -= 1

    if i < 0:
        perm.reverse()
        return True

    j = len(perm) - 1
    while perm[j] <= perm[i]:
        j -= 1

    perm[i], perm[j] = perm[j], perm[i]

    perm[i + 1:] = sorted(perm[i + 1:])

    return True

def jinjin_savings_plan(budgets: List[int]) -> int:
    balance = 0
    for month, budget in enumerate(budgets, start=1):
        if budget >= 100:
            balance += (budget + 300) * 1.2
        else:
            balance -= budget
        if balance < 0:
            return -month
    return int(balance)

