def jinjin_savings_plan(budgets: List[int]) -> int:
    total_saved = 0
    for month in range(12):
        if budgets[month] < 100:
            return -month
        month_savings = min(budgets[month], 300)
        total_saved += month_savings
        budgets[month] -= month_savings
