def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return n  # No formation possible
    if heights[0] < heights[-1]:  # The same height in both ends
        return 0  # No need to leave

    min_students_to_leave = n
    for i in range(1, n-1):
        if heights[i-1] >= heights[i] and heights[i] <= heights[i+1]:
            min_students_to_leave = n - i - 1
            break

    return min_students_to_leave

from typing import List

def minimum_students_to_leave(heights: List[int]) -> int:
    peak_index = heights.index(max(heights))
    left_students = sum(1 for i in range(peak_index))
    right_students = sum(1 for i in range(peak_index, len(heights)))
    return max(left_students, right_students)

