def min_groups(w, n, prices):
    prices.sort()
    total_cycles = 0
    while n > 0:
        min_price = prices[0]
        next_min_price = None
        for price in prices[1:]:
            if price + min_price <= w:
                if next_min_price is None or price < next_min_price:
                    next_min_price = price
        if next_min_price is None:
            break
        total_cycles += 1
        n -= 2
        prices.pop(0)
        prices.pop(0)
    return total_cycles + n // 2

def min_groups(w, n, prices):
    # 快速排序对 prices 进行排序
    prices.sort()
    i, j, count = 0, n - 1, 0
    while i <= j:
        if prices[i] + prices[j] <= w:
            i += 1  # 移动 i 指针，以增加组的数量
        j -= 1   # 移动 j 指针
        count += 1  # 每增加一个组，计数器增加 1
    return count

def min_groups(w, n, prices):
    prices.sort(reverse=True)
    groups = 0
    total_price = 0
    for price in prices:
        if total_price + price <= w:
            total_price += price
        else:
            total_price = price
            groups += 1
    return groups + 1 if total_price <= w else groups

def min_groups(w, n, prices):
    prices.sort(reverse=True)
    num_groups = 0
    remaining_w = w
    for price in prices:
        if remaining_w < price:
            return num_groups + 1
        remaining_w -= price
        num_groups += 1
    return num_groups

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14
    # Calculate the minimum number of moves using the known recursive formula for double-disc Towers.
    min_moves = 2 * ((2 ** n) - 2)
    return min_moves

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14
    moves = 0
    for i in range(2 * n):
        moves += n
    return moves

def hanoi_double_iterative(n: int) -> int:
    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive case
    return 4 * hanoi_double_iterative(n - 1) + 3

def total_smoked_cigarettes(n, k):
    discarded = 0
    while n >= k:
        n += discarded
        discarded, n = 0, n - k
    return n

def total_smoked_cigarettes(n, k):
    current cigarettes = n
    while current cigarettes >= k:
        cigarettes += current cigarettes // k
    return cigarettes
